#include "tscc/CompilationUnit.h"
#include "tscc/Transpiler.h"
#include <cstdlib>
#include <iostream>
using namespace tscc;static void fail(const char*m){std::cerr<<m<<'\n';std::exit(1);}static SourceFile source(std::string text){SourceFile s{"identity.ts",std::move(text),{0}};for(std::size_t i=0;i<s.text.size();++i)if(s.text[i]=='\n')s.line_starts.push_back(i+1);return s;}
int main(){CompilationUnit unit(source("interface User {name:string}\nconst answer:number=42;\nfunction read():number{return answer;}\n"));if(!unit.analyze())fail("valid unit failed");const auto count=unit.program.node_count();if(count!=4)fail("unexpected durable node count");for(std::size_t id=0;id<count;++id){const auto*n=unit.program.find_node(id);if(!n||n->id!=id||n->begin_offset>n->end_offset)fail("node identity/span missing");if(id&&n->parent_id!=unit.program.root.id)fail("parent identity missing");}const auto before=unit.program.find_node(2)->begin_offset;TranspileOptions options;if(!transpile_unit(unit,options))fail("emission failed");if(unit.program.node_count()!=count||unit.program.find_node(2)->begin_offset!=before)fail("identity changed after emission");CompilationUnit bad(source("function broken( {\nconst next:number=1;"));if(bad.analyze())fail("malformed unit accepted");bool recovered=false;for(const auto&n:bad.program.root.children)if(n.kind==SyntaxKind::Recovery&&n.recovered&&n.parent_id==bad.program.root.id)recovered=true;if(!recovered)fail("recovery node missing");std::cout<<"durable syntax identity passed\n";}
